import React, { useState } from 'react';

const VoiceWeb = ({ onNavigate }) => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState([]);
  const [step, setStep] = useState('init');

  const speak = (text) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
    setTranscript(prev => [...prev, { role: 'System', text }]);
  };

  const startListening = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event) => {
      const result = event.results[0][0].transcript.toLowerCase();
      setTranscript(prev => [...prev, { role: 'You', text: result }]);

      // LOGIC: After booking is done, we send PNR to backend
      if (result.includes('booking')) {
        const pnr = "SKY" + Math.floor(1000 + Math.random() * 9000);
        // Save to backend so Dashboard can track it
        fetch('http://localhost:5000/save-pnr', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ pnr })
        });
        speak(`Booking successful! Your PNR is ${pnr}. You can now go back and track it.`);
      }
    };
    recognition.start();
  };

  return (
    <div style={{ padding: '40px', background: '#f8fafc', minHeight: '100vh', textAlign: 'center' }}>
      <div style={{ maxWidth: '600px', margin: '0 auto', background: 'white', padding: '40px', borderRadius: '30px', boxShadow: '0 10px 30px rgba(0,0,0,0.05)' }}>
        <button onClick={() => onNavigate('dashboard')} style={{ float: 'left', background: 'none', border: 'none', color: '#1d4ed8', cursor: 'pointer' }}>← Back</button>
        <h2 style={{ marginBottom: '40px' }}>Voice Assistant</h2>

        <button 
          onClick={() => { speak("Hello, Welcome to SkySync. How can I help you?"); startListening(); }}
          style={{ width: '120px', height: '120px', borderRadius: '50%', border: 'none', background: isListening ? '#eff6ff' : '#1d4ed8', cursor: 'pointer' }}
        >
          <span style={{ fontSize: '40px' }}>{isListening ? '🌊' : '🎙️'}</span>
        </button>

        <div style={{ marginTop: '30px', textAlign: 'left', height: '200px', overflowY: 'auto', borderTop: '1px solid #eee', paddingTop: '20px' }}>
          {transcript.map((t, i) => (
            <p key={i}><b>{t.role}:</b> {t.text}</p>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VoiceWeb;
